// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.robustnessimport timber.log.Timberimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.core.OmniSlmRuntimeimport com.roshan.persona.vision.ocr.OcrResultimport com.roshan.persona.vision.ocr.TieredOcrResultimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Vision Failure Handler (Module 6 v4.2 — HIGH Priority Patch). * * Handles all 10 vision failure scenarios with user-friendly TTS feedback + * automatic recovery actions, per v4.2 §"Failure Modes" + reviewer's advice: * * > "prioritize VisionFailureHandler and First-frame parallel loading above * > all else. If the camera doesn't start reliably or the first result isn't * > fast, the quality of the Omni-SLM model will be irrelevant because the * > user will have already closed the app." * * ## Failure Scenarios (per v4.2 §"Failure Modes") * * | Failure | User Feedback | Recovery Action | * |---------|--------------|-----------------| * | Low light | "Too dark to read. Try turning on a light." | Offer flash | * | Blurry image | "Hold steady. The image is blurry." | Retry with longer exposure | * | No text found | "No text detected. Point at text." | None (user repositions) | * | Omni-SLM crash | Silent fallback to v2 stack | Auto-fallback to MiniLM + BERT-tiny | * | OCR gibberish | "I couldn't read this clearly. Please retake." | Retry with enhanced preprocessing | * | Camera permission denied | "I need camera access. Enable in Settings." | Guide to Settings | * | LMK kill | "NOUS was paused. Resuming..." | Auto-restore from encrypted cache | * | Thermal throttle | "Device is warm. Reducing performance." | Reduce FPS + resolution | * | Battery low | "Battery low. Switching to power-saving mode." | Disable captioning + reduce FPS | * | Model load failure | "Vision is warming up. Please wait..." | v2 stack fallback | * * ## Architecture * * [VisionFailureHandler] is the **single point of failure handling** for the * entire vision pipeline. Every engine (OcrEngine, ObjectDetectionEngine, * OmniSlmRuntime, etc.) routes failures here instead of silently returning * empty results. * * The handler: *  1. Classifies the failure type *  2. Generates user-friendly TTS message *  3. Suggests a recovery action *  4. Optionally auto-executes recovery (e.g., v2 stack fallback) *  5. Logs the failure for debugging * * @see <a href="docs/strategy/module-6-vision-strategy-v4.2-final.md">§Failure Modes</a> */class VisionFailureHandler(    private val dispatcher: CoroutineDispatcher,) {    /** Total failures handled (for stats + debugging). */    @Volatile    private var totalFailuresHandled: Int = 0    /** Failure count by type (for debugging + telemetry). */    private val failureCounts = mutableMapOf<VisionFailureType, Int>()    /** Recent failures (last 20, for debugging). */    private val recentFailures = mutableListOf<VisionFailureRecord>()    /**     * Handle a vision failure.     *     * @param failureType the type of failure.     * @param context optional context (e.g., which engine failed, error message).     * @return the [VisionFailureResponse] with user message + recovery action.     */    suspend fun handleFailure(        failureType: VisionFailureType,        context: VisionFailureContext = VisionFailureContext(),    ): VisionFailureResponse = withContext(dispatcher) {        totalFailuresHandled++        failureCounts[failureType] = (failureCounts[failureType] ?: 0) + 1        val record = VisionFailureRecord(            type = failureType,            timestampMs = System.currentTimeMillis(),            engineName = context.engineName,            errorMessage = context.errorMessage,        )        synchronized(recentFailures) {            recentFailures.add(record)            if (recentFailures.size > 20) recentFailures.removeAt(0)        }        Timber.tag(TAG).w("Vision failure: $failureType (engine=${context.engineName}, error=${context.errorMessage}).")        val response = when (failureType) {            VisionFailureType.LOW_LIGHT -> VisionFailureResponse(                userMessage = "Too dark to read. Try turning on a light.",                spokenMessage = "Too dark to read. Try turning on a light or enabling flash.",                recoveryAction = RecoveryAction.OFFER_FLASH,                shouldRetry = false,                shouldFallback = false,            )            VisionFailureType.BLURRY_IMAGE -> VisionFailureResponse(                userMessage = "Hold steady. The image is blurry.",                spokenMessage = "Hold steady. The image is blurry. Let me try again.",                recoveryAction = RecoveryAction.RETRY_WITH_LONGER_EXPOSURE,                shouldRetry = true,                shouldFallback = false,            )            VisionFailureType.NO_TEXT_FOUND -> VisionFailureResponse(                userMessage = "No text detected. Point at text.",                spokenMessage = "I don't see any text. Point the camera at something with writing.",                recoveryAction = RecoveryAction.NONE,                shouldRetry = false,                shouldFallback = false,            )            VisionFailureType.OMNI_SLM_CRASH -> VisionFailureResponse(                userMessage = null,  // Silent — user shouldn't know Omni-SLM crashed                spokenMessage = null,                recoveryAction = RecoveryAction.FALLBACK_TO_V2_STACK,                shouldRetry = false,                shouldFallback = true,            )            VisionFailureType.OCR_GIBBERISH -> VisionFailureResponse(                userMessage = "I couldn't read this clearly. Please retake.",                spokenMessage = "I couldn't read this clearly. Please hold steady and try again.",                recoveryAction = RecoveryAction.RETRY_WITH_ENHANCED_PREPROCESSING,                shouldRetry = true,                shouldFallback = false,            )            VisionFailureType.CAMERA_PERMISSION_DENIED -> VisionFailureResponse(                userMessage = "I need camera access. Enable in Settings → Apps → NOUS → Permissions.",                spokenMessage = "I need camera access to see. Please enable camera permission in Settings.",                recoveryAction = RecoveryAction.GUIDE_TO_SETTINGS,                shouldRetry = false,                shouldFallback = false,            )            VisionFailureType.LMK_KILL -> VisionFailureResponse(                userMessage = "NOUS was paused. Resuming...",                spokenMessage = "NOUS was paused. Resuming vision.",                recoveryAction = RecoveryAction.RESTORE_FROM_ENCRYPTED_CACHE,                shouldRetry = false,                shouldFallback = false,            )            VisionFailureType.THERMAL_THROTTLE -> VisionFailureResponse(                userMessage = "Device is warm. Reducing performance.",                spokenMessage = "Device is getting warm. Reducing vision performance to prevent overheating.",                recoveryAction = RecoveryAction.REDUCE_FPS_AND_RESOLUTION,                shouldRetry = false,                shouldFallback = false,            )            VisionFailureType.BATTERY_LOW -> VisionFailureResponse(                userMessage = "Battery low. Switching to power-saving mode.",                spokenMessage = "Battery is low. Switching to power-saving vision mode. Captioning disabled.",                recoveryAction = RecoveryAction.DISABLE_CAPTIONING_REDUCE_FPS,                shouldRetry = false,                shouldFallback = false,            )            VisionFailureType.MODEL_LOAD_FAILURE -> VisionFailureResponse(                userMessage = "Vision is warming up. Please wait...",                spokenMessage = "Vision is warming up. This takes a few seconds on first use.",                recoveryAction = RecoveryAction.FALLBACK_TO_V2_STACK,                shouldRetry = false,                shouldFallback = true,            )            VisionFailureType.UNKNOWN -> VisionFailureResponse(                userMessage = "Something went wrong. Please try again.",                spokenMessage = "Something went wrong with vision. Please try again.",                recoveryAction = RecoveryAction.NONE,                shouldRetry = false,                shouldFallback = false,            )        }        Timber.tag(TAG).d("Failure response: message=${response.spokenMessage}, action=${response.recoveryAction}.")        response    }    /**     * Wrap an OCR result — if rejected or low-confidence, handle as failure.     *     * @param ocrResult the OCR result to check.     * @return the original result if usable, or a failure response if rejected.     */    suspend fun wrapOcrResult(ocrResult: TieredOcrResult): VisionResultOrFailure<OcrResult> = withContext(dispatcher) {        val ocrValue = ocrResult.value        if (ocrResult.isUsable && ocrValue != null) {            VisionResultOrFailure.Success(ocrValue)        } else {            val failureType = when {                ocrResult.value?.blocks?.isEmpty() == true -> VisionFailureType.NO_TEXT_FOUND                ocrResult.confidence < 0.35f -> VisionFailureType.OCR_GIBBERISH                else -> VisionFailureType.UNKNOWN            }            val response = handleFailure(failureType, VisionFailureContext(                engineName = "OcrEngine",                errorMessage = "OCR tier=${ocrResult.tier}, confidence=${ocrResult.confidence}",            ))            VisionResultOrFailure.Failure(response)        }    }    /**     * Wrap an Omni-SLM result — if rejected, handle as failure + suggest v2 fallback.     */    suspend fun <T> wrapOmniSlmResult(        result: ConfidenceTieredResult<T>,        engineName: String,    ): VisionResultOrFailure<T> = withContext(dispatcher) {        val value = result.value        if (result.isUsable && value != null) {            VisionResultOrFailure.Success(value)        } else {            val response = handleFailure(                VisionFailureType.OMNI_SLM_CRASH,                VisionFailureContext(engineName = engineName, errorMessage = "Omni-SLM tier=${result.tier}"),            )            VisionResultOrFailure.Failure(response)        }    }    /** Get failure stats (for Settings → Debug → Vision Failures). */    fun stats(): VisionFailureStats = VisionFailureStats(        totalFailuresHandled = totalFailuresHandled,        failureCounts = failureCounts.toMap(),        recentFailures = synchronized(recentFailures) { recentFailures.toList() },    )    /** Clear failure stats (for debugging). */    fun clearStats() {        totalFailuresHandled = 0        failureCounts.clear()        synchronized(recentFailures) { recentFailures.clear() }    }    private companion object {        private const val TAG = "VisionFailureHandler"    }}// ──────────────────────────────────────────────────────────────────────────/** Types of vision failures. */enum class VisionFailureType(val displayName: String) {    LOW_LIGHT("Low Light"),    BLURRY_IMAGE("Blurry Image"),    NO_TEXT_FOUND("No Text Found"),    OMNI_SLM_CRASH("Omni-SLM Crash"),    OCR_GIBBERISH("OCR Gibberish"),    CAMERA_PERMISSION_DENIED("Camera Permission Denied"),    LMK_KILL("LMK Kill"),    THERMAL_THROTTLE("Thermal Throttle"),    BATTERY_LOW("Battery Low"),    MODEL_LOAD_FAILURE("Model Load Failure"),    UNKNOWN("Unknown Failure");}/** Context for a failure (which engine, what error). */data class VisionFailureContext(    val engineName: String? = null,    val errorMessage: String? = null,)/** Response to a failure — user message + recovery action. */data class VisionFailureResponse(    /** User-facing text message (null = silent failure, no UI). */    val userMessage: String?,    /** TTS spoken message (null = silent). */    val spokenMessage: String?,    /** What recovery action to take. */    val recoveryAction: RecoveryAction,    /** True if the engine should retry the operation. */    val shouldRetry: Boolean,    /** True if the engine should fall back to v2 stack. */    val shouldFallback: Boolean,)/** Recovery actions the engine can take. */enum class RecoveryAction(val displayName: String) {    /** No automatic recovery — user must act. */    NONE("None"),    /** Offer to enable flash for better lighting. */    OFFER_FLASH("Offer Flash"),    /** Retry with longer camera exposure (reduces blur). */    RETRY_WITH_LONGER_EXPOSURE("Retry with Longer Exposure"),    /** Retry with stronger image enhancement (denoise + contrast). */    RETRY_WITH_ENHANCED_PREPROCESSING("Retry with Enhanced Preprocessing"),    /** Fall back to v2 stack (MiniLM + BERT-tiny + MobileViT). */    FALLBACK_TO_V2_STACK("Fallback to v2 Stack"),    /** Guide user to Settings to grant camera permission. */    GUIDE_TO_SETTINGS("Guide to Settings"),    /** Restore episodic memory + KV cache from encrypted disk cache. */    RESTORE_FROM_ENCRYPTED_CACHE("Restore from Encrypted Cache"),    /** Reduce FPS + switch to 720p + grayscale (thermal throttle). */    REDUCE_FPS_AND_RESOLUTION("Reduce FPS and Resolution"),    /** Disable captioning + reduce FPS (battery low). */    DISABLE_CAPTIONING_REDUCE_FPS("Disable Captioning + Reduce FPS"),}/** A failure record (for debugging). */data class VisionFailureRecord(    val type: VisionFailureType,    val timestampMs: Long,    val engineName: String?,    val errorMessage: String?,)/** Failure stats (for Settings → Debug). */data class VisionFailureStats(    val totalFailuresHandled: Int,    val failureCounts: Map<VisionFailureType, Int>,    val recentFailures: List<VisionFailureRecord>,)// ──────────────────────────────────────────────────────────────────────────/** * Sealed result — either a success value or a failure response. * * Used by [VisionFailureHandler.wrapOcrResult] + [VisionFailureHandler.wrapOmniSlmResult]. */sealed interface VisionResultOrFailure<out T> {    data class Success<T>(val value: T) : VisionResultOrFailure<T>    data class Failure<T>(val response: VisionFailureResponse) : VisionResultOrFailure<T>    val isSuccess: Boolean get() = this is Success    val isFailure: Boolean get() = this is Failure    fun getOrNull(): T? = (this as? Success)?.value    fun failureOrNull(): VisionFailureResponse? = (this as? Failure)?.response}
